fn analyze_dependencies(expr: &Expr, component: &Component) -> HashSet<Dependency> {
    let mut deps: HashSet<Dependency> = HashSet::new();

    fn walk(expr: &Expr, component: &Component, deps: &mut HashSet<Dependency>) {
        match expr {
            Expr::Ident(ident) => {
                let name = ident.sym.to_string();
                if let Some(state_type) = component.state_types.get(&name) {
                    deps.insert(Dependency {
                        name: name.clone(),
                        dep_type: state_type.clone(),
                    });
                }
            }
            Expr::Cond(cond) => {
                walk(&cond.test, component, deps);
                walk(&cond.cons, component, deps);
                walk(&cond.alt, component, deps);
            }
            Expr::Bin(bin) => {
                walk(&bin.left, component, deps);
                walk(&bin.right, component, deps);
            }
            Expr::Member(member) => {
                walk(&member.obj, component, deps);
                if let MemberProp::Computed(computed) = &member.prop {
                    walk(&computed.expr, component, deps);
                }
            }
            Expr::Call(call) => {
                if let Callee::Expr(callee) = &call.callee {
                    walk(callee, component, deps);
                }
                for arg in &call.args {
                    walk(&arg.expr, component, deps);
                }
            }
            Expr::Unary(unary) => {
                walk(&unary.arg, component, deps);
            }
            Expr::Arrow(arrow) => {
                if let BlockStmtOrExpr::Expr(body) = &*arrow.body {
                    walk(body, component, deps);
                }
            }
            _ => {}
        }
    }

    walk(expr, component, &mut deps);
    deps
}
